{"content": "import json, re, collections

paper = open('/home/user/gp-rarelink/data/literature/ssadh/fulltext_md/33203024.md').read()
d = json.load(open('/home/user/gp-rarelink/data/extracted/ssadh/ow-ssadh/per_paper/33203024.json'))

def check(span, path, problems):
    if span is None:
        return
    if isinstance(span, list):
        for s in span:
            check(s, path, problems)
        return
    if span not in paper:
        problems.append((path, span))

problems = []
counts = {}
for tname, rows in d['tables'].items():
    counts[tname] = len(rows)
    for i, row in enumerate(rows):
        for f, cell in row.items():
            check(cell.get('span'), f'{tname}[{i}].{f}', problems)

print('rows per table:', counts)
labels = [r['individual_label_in_paper']['value'] for r in d['tables']['individuals']]
print('individuals:', len(labels), labels)

# checklist completeness
feats = ["intellectual disability","speech or language impairment","hypotonia","gross or fine motor deficits","seizures or epilepsy","EEG abnormality (background slowing or epileptiform activity)","ataxia","dystonia","exertional dyskinesia","hemiballismus","autism spectrum disorder or autistic behaviors","attention problems or ADHD","anxiety","obsessive-compulsive traits","aggression or disruptive behavior","sleep disturbances","depression or mood fluctuation","psychotic symptoms (hallucinations or delusions)","T2 hyperintensity of globus pallidus, subthalamic or dentate nuclei on MRI","cerebral or cerebellar atrophy"]
cl = collections.Counter()
for r in d['tables']['phenotype_checklist']:
    cl[(r['individual_label_in_paper']['value'], r['checklist_feature']['value'])] += 1
bad = [k for k,v in cl.items() if v != 1]
missing = [(l,f) for l in labels for f in feats if (l,f) not in cl]
print('checklist rows:', len(d['tables']['phenotype_checklist']), 'dup/odd:', bad, 'missing:', missing)
print('checklist statuses:', collections.Counter(r['status']['value'] for r in d['tables']['phenotype_checklist']))
# status not reported => evidence_basis must be not reported and span null
for r in d['tables']['phenotype_checklist']:
    if r['status']['value'] == 'not reported':
        assert r['evidence_basis']['value'] == 'not reported' and r['evidence_basis']['span'] is None, r
    else:
        assert r['evidence_basis']['value'] in ('stated for this individual','inferred from group statement')
        assert r['status']['span'] is not None, r
# field completeness
schema = json.load(open('/home/user/gp-rarelink/pipeline/extract/claude_code/schema_ssadh_v5.json'))
for t in schema['tables']:
    names = [f['name'] for f in t['fields']]
    for row in d['tables'][t['name']]:
        assert sorted(row.keys()) == sorted(names), (t['name'], set(names) ^ set(row.keys()))
# label consistency across tables
lab_sets = {t: set(r['individual_label_in_paper']['value'] for r in d['tables'][t]) for t in ['individuals','variants','phenotypic_features','phenotype_checklist']}
print('labels per table:', {k: len(v) for k,v in lab_sets.items()}, 'subset check:', all(v <= lab_sets['individuals'] for v in lab_sets.values()))
print('phenotypic_features rows:', len(d['tables']['phenotypic_features']), 'statuses:', collections.Counter(r['status']['value'] for r in d['tables']['phenotypic_features']))
print('span problems:', problems)
